def solve(rows):
    # Keep only rows where result is not 'late'
    non_late_rows = [row for row in rows if row['result'] != 'late']

    if not non_late_rows:
        return [0, None]

    # Extract day values
    days = [row['day'] for row in non_late_rows]

    # Find the longest block of consecutive integers
    max_length = 1
    current_length = 1
    start_day = days[0]

    for i in range(1, len(days)):
        if days[i] == days[i - 1] + 1:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
                start_day = days[i - current_length + 1]
        else:
            current_length = 1

    if max_length == 1:
        return [0, None]
    else:
        return [max_length, start_day]
