def solve(rows):
    if not rows:
        return 0

    # Group rows by driver
    driver_packages = {}
    for row in rows:
        driver = row["driver"]
        packages = row["packages"]
        if driver not in driver_packages:
            driver_packages[driver] = []
        driver_packages[driver].append(packages)

    # Calculate median for each driver
    median_packages = {}
    for driver, packages in driver_packages.items():
        packages.sort()
        n = len(packages)
        if n % 2 == 1:
            median = packages[n // 2]
        else:
            median = (packages[n // 2 - 1] + packages[n // 2]) / 2
        median_packages[driver] = round(median, 1)

    # Sum the rounded median packages
    total_packages = sum(median_packages.values())
    return total_packages
