def solve(rows):
    # Filter rows where outcome is not 'no_show'
    filtered_rows = [row for row in rows if row['outcome'] != 'no_show']

    # Calculate total duration_min * fee for each department
    department_totals = {}
    for row in filtered_rows:
        department = row['department']
        duration = row['duration_min']
        fee = row['fee']
        total = duration * fee
        if department in department_totals:
            department_totals[department] += total
        else:
            department_totals[department] = total

    # Find the department with the highest total, and alphabetically first on tie
    if not department_totals:
        return None

    max_total = max(department_totals.values())
    candidates = [dept for dept, total in department_totals.items() if total == max_total]
    return min(candidates)
```

