        if days[i] == days[i-1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                start_day = days[i-1 - (current_length - 1)]
            current_length = 1
    if current_length > max_length:
        max_length = current_length
        start_day = days[-1 - (current_length - 1)]
    return [max_length, start_day]
