def solve(rows):
    # Filter rows where outcome is not 'no_show'
    filtered_rows = [row for row in rows if row['outcome'] != 'no_show']

    # Extract all doctors and their corresponding duration_min
    doctor_duration = {}
    for row in filtered_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor in doctor_duration:
            doctor_duration[doctor].append(duration)
        else:
            doctor_duration[doctor] = [duration]

    # Calculate median duration for each doctor
    median_durations = {}
    for doctor, durations in doctor_duration.items():
        durations.sort()
        n = len(durations)
        if n % 2 == 1:
            median = (durations[n // 2] + durations[n // 2 + 1]) / 2
        else:
            median = (durations[n // 2] + durations[n // 2 - 1]) / 2
        median_durations[doctor] = round(median, 1)

    # Get distinct doctors and sort them
    distinct_doctors = sorted(median_durations.keys())
    return distinct_doctors
