def solve(rows):
    # Initialize balance and tracking variables
    balance = 0
    min_balance = 0
    min_day = None

    # Process rows in ascending order (by day, then visit_id)
    for row in sorted(rows, key=lambda x: (x['day'], x['visit_id'])):
        outcome = row['outcome']

        if outcome == 'no_show':
            balance += row['duration_min']
        elif outcome == 'completed':
            balance -= row['duration_min']

        # Update min_balance and min_day if balance changes
        if balance != min_balance:
            min_balance = balance
            min_day = row['day']

    # Return the result
    if min_balance != 0:
        return [min_balance, min_day]
    else:
        return [0, None]
